(function(){const markup="<section class=\"client-snapshots\" aria-label=\"Client account and reel snapshots\"><header><small>CLIENT ACCOUNTS / FOLLOWER SNAPSHOTS</small><h3>My beloved client's success</h3><p>Selected client account snapshots. Names and identifying details withheld. Counts as captured in October 2026.</p></header><div class=\"follower-rows\"><figure><img src=\"data:image/jpeg;base64,\" alt=\"201K followers\"></figure><figure><img src=\"data:image/jpeg;base64,\" alt=\"172K followers\"></figure><figure><img src=\"data:image/jpeg;base64,\" alt=\"106K followers\"></figure></div><header><small>CLIENT REELS / VIEW SNAPSHOTS</small><h3>Karm karo, fal bhi milega!\ud83d\udcc8</h3><p>Multiple result variations across multiple accounts.</p></header><div class=\"view-rows\"><figure><img src=\"data:image/jpeg;base64,\" alt=\"Reel view counts: 11.2M / 9.4M / 7.2M\"></figure><figure><img src=\"data:image/jpeg;base64,\" alt=\"Reel view counts: 8.2M / 1.2M / 1.2M\"></figure><figure><img src=\"data:image/jpeg;base64,\" alt=\"Reel view counts: 6.9M / 6.7M / 6M\"></figure><figure><img src=\"data:image/jpeg;base64,\" alt=\"Reel view counts: 5.5M / 4.9M / 4.3M\"></figure><figure><img src=\"data:image/jpeg;base64,\" alt=\"Reel view counts: 2.1M / 651K / 391K\"></figure></div></section>";const css=".client-snapshots{margin:32px 0;padding:28px;background:#fff;color:#16121c;border:3px solid #16121c;box-shadow:6px 6px 0 #f9df00}.client-snapshots header{margin:0 0 20px}.client-snapshots header+div{margin-bottom:32px}.client-snapshots small{font-weight:800;letter-spacing:.07em;color:#833dff}.client-snapshots h3{font-family:Antonio,Impact,sans-serif;font-size:clamp(28px,4vw,48px);margin:12px 0}.client-snapshots p{line-height:1.6;margin:12px 0}.client-snapshots figure{margin:0 0 16px;border:2px solid #16121c;background:#0b1014}.client-snapshots img{display:block;width:100%;height:auto;object-fit:contain}.client-snapshots .follower-rows figure{display:flex;justify-content:center}.client-snapshots .follower-rows img{width:min(100%,318px)}@media(max-width:600px){.client-snapshots{padding:16px;box-shadow:4px 4px 0 #f9df00;margin-right:4px}}";function add(){const anchors=Array.from(document.querySelectorAll("#results .rs-proofs,.ogchapter .oggrid"));anchors.forEach(function(anchor){if(anchor.nextElementSibling&&anchor.nextElementSibling.classList.contains("client-snapshots"))return;if(!document.getElementById("client-snapshots-css")){const style=document.createElement("style");style.id="client-snapshots-css";style.textContent=css;document.head.appendChild(style);}const box=document.createElement("div");box.innerHTML=markup;anchor.after(box.firstElementChild);});}add();new MutationObserver(add).observe(document.documentElement,{childList:true,subtree:true});})();
